           FROM card_sets s
          WHERE s.pullable
        UNION
         SELECT r.pool_set_id,
            i.included_set_id
           FROM reach r
             JOIN set_includes i ON i.set_id = r.src_set_id
        ), members(pool_set_id, card_id) AS (
         SELECT r.pool_set_id,
            c_1.id
           FROM reach r
             JOIN cards c_1 ON c_1.set_id = r.src_set_id
        UNION
         SELECT r.pool_set_id,
            p.card_id
           FROM reach r
             JOIN set_pool p ON p.set_id = r.src_set_id
        )
 SELECT m.pool_set_id,
    c.id,
    c.subject_id,
    c.name,
    c.rarity,
    c.source,
    c.image_url,
    c.artist_credit,
    c.lore,
    c.set_id,
    c.set_number
   FROM members m
     JOIN cards c ON c.id = m.card_id
  WHERE c.in_draw_pool AND c.source::text = 'draw'::text;

